bool cast_brand_icon_loader(void *user, cui_str path, cui_str *svg)
{
    (void)user;
    if (!svg || !path.data) return false;
    if (path.length >= 6 && !memcmp(path.data, "icons/", 6)) {
        path.data += 6; path.length -= 6;
    }
    if (path.length >= 4 && !memcmp(path.data + path.length - 4, ".svg", 4))
        path.length -= 4;
    for (size_t i = 0; i < sizeof icons / sizeof icons[0]; ++i) {
        if (strlen(icons[i].name) == path.length &&
            !memcmp(icons[i].name, path.data, path.length)) {
            *svg = cui_string(icons[i].svg);
            return true;
        }
    }
    return false;
}
void cast_brand_apply(cui_theme *theme)
{
    if (!theme) return;
    theme->icon_loader = cast_brand_icon_loader;
    theme->icon_loader_user = NULL;
    theme->icon_revision = 1;
}

